CREATE OR REPLACE FUNCTION fn_generate_financial_document_number()
RETURNS TRIGGER
AS
$$
BEGIN
  IF NEW.document_number IS NULL OR BTRIM(NEW.document_number) = '' THEN
    RAISE EXCEPTION
      'Financial document number must be assigned from numbering setup before insert';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
